export const dictionaries = { en, ta };
export type Locale = keyof typeof dictionaries;
export const LOCALES: Locale[] = ['en', 'ta'];
export const LOCALE_NAMES: Record<Locale, string> = { en: 'English', ta: 'தமிழ் (Tamil)' };

/** Substitutes {0}, {1}... positional placeholders. */
export function format(template: string, ...args: (string | number)[]): string {
  return template.replace(/\{(\d+)\}/g, (m, i) => String(args[Number(i)] ?? m));
}
